function columns(n) {
  const tracks = Array(n).fill('1fr').join(' ');
  return 'grid-template-columns: ' + tracks + ';';
}

function spanCols(start, end) {
  return 'grid-column: ' + start + ' / ' + end + ';';
}

function twoByTwo() {
  return 'display: grid; grid-template-columns: 1fr 1fr; grid-template-rows: 1fr 1fr;';
}
